use vstd::prelude::*;

verus! {

spec fn all_leq(s: Seq<i32>, e: i32) -> bool {
    forall|i: int| 0 <= i < s.len() ==> s[i] <= e
}

spec fn is_subsequence_of(sub: Seq<i32>, sup: Seq<i32>) -> bool {
    exists|f: int -> int|
        // f maps indices of `sub` into indices of `sup`
        (forall|i: int| 0 <= i < sub.len() ==> 0 <= f(i) < sup.len())
        && (forall|i: int, j: int| 0 <= i < j < sub.len() ==> f(i) < f(j))
        && (forall|i: int| 0 <= i < sub.len() ==> sub[i] == sup[f(i)])
}

pub fn remove_all_greater(v: Vec<i32>, e: i32) -> (out: Vec<i32>)
    ensures
        // output contains no elements greater than e
        all_leq(out@, e),
        // every output element came from the input, in the same relative order
        is_subsequence_of(out@, v@),
        // output contains exactly the input elements that are <= e (as a multiset)
        out@.to_multiset() == v@.filter(|x: i32| x <= e).to_multiset(),
{
    v.into_iter().filter(|&x| x <= e).collect()
}

}

